// Pipeline Registers defining data flow between stages
typedef struct {
    uint64_t predPC;
    instr_t instruction;
} FD_Reg;

typedef struct {
    op_code_t Op;
    uint64_t rA, rB;    // Source register IDs
    uint64_t valC;
    bool needs_valB;
} DE_Reg;

typedef struct {
    uint64_t valE;      // ALU result
    uint64_t valA;      // Passthrough data
    reg_id_t dstE, dstM;
    bool Cnd;           // Condition flags
} EM_Reg;

// Data Hazard Forwarding Logic (E Stage input sourcing)
uint64_t fwd_valA(reg_id_t srcA) {
    if (srcA == E_M.dstE) return E_M.valE;   // E -> E Forward
    if (srcA == M_W.dstM) return M_W.valM;   // M -> E Forward
    if (srcA == M_W.dstE) return M_W.valE;   // W -> E Forward (ALU)
    // Default: Read from Register File
    return RegFile[srcA];
}

// Control Hazard Handling (Branch Prediction/Correction)
void update_PC(uint64_t new_PC) {
    // Determine if branch was taken (M Stage)
    if (M_W.branch_OP && !M_W.Cnd) {
        // Misprediction: Flush D, E, M stages
        F_D.stat = S_BUB;
        D_E.stat = S_BUB;
        E_M.stat = S_BUB;
    }
    F_D.PC = new_PC;
}

// Load/Use Hazard Detection (D Stage stall criteria)
bool check_load_use_hazard(const DE_Reg D_E, const FD_Reg F_D) {
    bool is_load = (D_E.Op == I_MRMOVL || D_E.Op == I_POPQ);
    if (!is_load) return false;

    // Check if destination (dstM) is used immediately by instruction in F_D
    if (D_E.dstM == F_D.rA || D_E.dstM == F_D.rB) {
        // Need to stall D stage and bubble E stage
        return true;
    }
    return false;
}
